const enterUnit = useCallback(() => {
  const at = now();
  // The unit's clock starts with it, when the pack or the mode runs one.
  const clock = unitClockStart(pack, state, nextUnit(state), at);
  commit([{ t: "UnitEntered", at }, ...(clock ? [clock] : [])]);
}, [commit, pack, state]);

const declareSubject = useCallback(
  (phase: Phase, index: number, subjectType: string) => completeStep(phase, index, [{ t: "SubjectDeclared", at: now(), subjectType }]),
  [completeStep],
);

const finalizeUnit = useCallback(
  (phase: Phase, index: number) => {
    const at = now();
    // Every live clock stops with the unit, its time written in.
    completeStep(phase, index, [...(state ? stopClocksEvents(state, at) : []), { t: "UnitFinalized", at }]);
  },
  [completeStep, state],
);

/**
 * The closing step's fork. Next closes the unit and enters the next in
 * one press, the new unit's clock starting with it; Finish closes the
 * unit and, where the pack offers one ending or none, ends the run with
 * it, else leaves the endings to choose from between units.
const writeJournal = useCallback((unit: number, text: string) => commit([{ t: "JournalWritten", at: now(), unit, text }]), [commit]);

const endRun = useCallback((ending: string) => commit([{ t: "RunEnded", at: now(), ending }]), [commit]);

/** Moves offered at this point in the flow. */
const moves = useMemo(() => {
  if (!state || state.status === "ended") return [];
  // Ending moves are offered alongside the between-units ones, because that
  // is the one moment the player is deciding whether to stop. Asked for in a
  // single call: two calls counted every `anytime` move twice.
  return availableMoves(pack, state, activeStep ? "anytime" : ["betweenUnits", "beforeEnding"]);
}, [pack, state, activeStep]);

/**
 * Take a move, for the table or for one racer.
 *
 * The contestant is not a fifth argument for the sake of it: a move a
 * pack marks `per: contestant` is a different move for each name on
 * the roster, and what it does has to be recorded against the one who
 * took it or a race has one death counter between four people.
 */
const takeMove = useCallback(
  (id: string, label: string, askedBy?: { name?: string; via?: string }, contestant?: string) =>
    begin({
      kind: "move",
      moveId: id,
      keyPrefix: contestant ? `move:${id}:${contestant}` : `move:${id}`,
      label,
      ...(pack.moves?.[id]?.finalizes ? { closesUnit: true } : {}),
      ...(askedBy ? { askedBy } : {}),
      ...(contestant ? { contestant } : {}),
    }),
  [begin, pack],
);

/* ---- moderated play: the roster, the challenges, the awards ---- */

const moderated = useMemo(() => moderation(pack, state), [pack, state]);
const challengeList = useMemo(() => (state && moderated ? challenges(pack, state) : []), [pack, state, moderated]);
const standingsList = useMemo(() => (state ? standings(state) : []), [state]);

/**
 * The moderator's word: this contestant finished this drawn result.
 *
 * In a race this *is* the declaration that somebody settled it, so
 * the mode can say what settling pays and it is drawn here, for them.
 * A pack that puts a move in front of the same sentence is asking for
 * the same thing twice, and the second press was always going to be
 * the one that got forgotten.
 */
const award = useCallback(
  (contestant: string, outcome: number) => {
    if (!state) return;
    const value = awardValue(pack, state, outcome, contestant);
    const o = state.outcomes[outcome];
    if (value === null || !o) return;
    commit([{ t: "Awarded", at: now(), contestant, outcome, table: o.table, entryId: o.entryId, points: value }]);
    const pays = moderation(pack, state)?.onAward;
    if (!pays || pays.length === 0) return;
